(function(root){
const day=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const plus=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return day(d);};
const mins=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function parse(input,base){let title=input.trim(),date='',start='',duration=30,kind='inbox';const lower=title.toLowerCase(),time=lower.match(/\b(?:alle|ore)\s+(\d{1,2})(?:[:.](\d{2}))?\b/),dur=lower.match(/\b(?:per|durata)\s+(\d+)\s*(minuti|min|ore|ora)\b/);if(dur){duration=Number(dur[1])*(dur[2].startsWith('or')?60:1);title=title.replace(dur[0],'');}if(time){start=Number(time[1])>23||Number(time[2]||0)>59?'invalid':clock(Number(time[1])*60+Number(time[2]||0));title=title.replace(new RegExp(time[0],'i'),'');}
if(/\bdopodomani\b/.test(lower)){date=plus(base,2);title=title.replace(/\bdopodomani\b/i,'');}else if(/\bdomani\b/.test(lower)){date=plus(base,1);title=title.replace(/\bdomani\b/i,'');}else if(/\boggi\b/.test(lower)){date=base;title=title.replace(/\boggi\b/i,'');}else{const weekdays=['domenica','lunedì','martedì','mercoledì','giovedì','venerdì','sabato'];for(let i=0;i<7;i++)if(lower.includes(weekdays[i])){const delta=(i-new Date(base+'T12:00:00').getDay()+7)%7;date=plus(base,delta||7);title=title.replace(new RegExp(weekdays[i],'i'),'');break;}}
if(/^(comprare|acquistare|spesa:)\s*/i.test(title)){kind='shop';title=title.replace(/^(comprare|acquistare|spesa:)\s*/i,'');}else if(/^lavoro:\s*/i.test(title)){kind='work';title=title.replace(/^lavoro:\s*/i,'');}else if(/^famiglia:\s*/i.test(title)){kind='family';title=title.replace(/^famiglia:\s*/i,'');}else if(date||start)kind='block';return {title:title.replace(/\s+/g,' ').trim(),date:date||base,start:start||'09:00',duration,kind,hasTime:!!start,hasDate:!!date};}
function nowSlots(inbox,blocks,now,available){const date=day(now),start=Math.ceil((now.getHours()*60+now.getMinutes()+1)/5)*5;return inbox.filter(t=>{const f=root.GiornoSlots.defaults(t),end=start+f.duration;return !f.waiting&&f.duration<=available&&end<=now.getHours()*60+now.getMinutes()+available&&f.days.includes(now.getDay())&&(!f.after||f.after<=date)&&(!f.deadline||f.deadline>=date)&&start>=mins(f.from)&&end<=mins(f.to)&&end<1440&&!blocks.some(b=>b.date===date&&mins(b.start)<end&&start<mins(b.end));}).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')).slice(0,3).map(t=>({id:t.id,title:t.title,date,start:clock(start),end:clock(start+root.GiornoSlots.defaults(t).duration)}));}
root.GiornoSmart={parse,nowSlots};
})(globalThis);
